import{_ as a,o,c as r,ag as t}from"./chunks/framework.B_zcDAFh.js";const p=JSON.parse('{"title":"Boing Reactor","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-reactor.md","filePath":"guide/boing-reactor.md"}'),n={name:"guide/boing-reactor.md"};function s(i,e,c,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="boing-reactor" tabindex="-1">Boing Reactor <a class="header-anchor" href="#boing-reactor" aria-label="Permalink to &quot;Boing Reactor&quot;">​</a></h1><p>Add the <strong>Boing Reactor</strong> component to an object that should be <em>pushed</em> by nearby <a href="./boing-effector.html">Boing Effectors</a>.</p><p>A reactor is a superset of a <a href="./boing-behavior.html">Boing Behavior</a>: once added, the object exhibits the same self-driven bouncy response <em>and</em> additionally responds to effector influence in the scene.</p><h2 id="when-to-use-a-reactor-vs-a-reactor-field" tabindex="-1">When to Use a Reactor vs a Reactor Field <a class="header-anchor" href="#when-to-use-a-reactor-vs-a-reactor-field" aria-label="Permalink to &quot;When to Use a Reactor vs a Reactor Field&quot;">​</a></h2><p>A reactor processes each object individually. If you have a small number of distinct objects (a row of bushes, a chest of collectibles, a few decorative props), per-object reactors are the simplest setup.</p><p>When you need many objects to respond to the same effector across a large area, prefer a <a href="./boing-reactor-field.html">Boing Reactor Field</a> — it amortizes the work across a single grid and can be sampled from shaders.</p><p>See the <a href="/boing-kit/api/boing-reactor.html">API reference</a> for properties, and the <a href="/boing-kit/gallery/effector-reactor.html">Effector &amp; Reactor gallery</a> for example scenes.</p>',7)])])}const b=a(n,[["render",s]]);export{p as __pageData,b as default};
